fn frame(t: i32) {
    host::display::clear(0x0c0e13);
    let has: i32 = host::agent::viewer_has_identity();
    let subbed: i32 = host::agent::is_subscribed();
    let count: i32 = host::agent::subscriber_count();
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    host::display::state_set(0, down);
    let mut click: i32 = 0;
    if down == 1 && prev == 0 {
        click = 1;
    }

    if subbed == 1 {
        host::display::fill_rect(76, 130, 360, 220, 0x152a1a);
        host::display::fill_rect(76, 130, 360, 8, 0x33ff88);
        host::display::draw_string(100, 170, "MEMBER CARD", 0x99ffbb, 3);
        host::display::draw_string(100, 240, "CLUB SIZE", 0x557766, 1);
        host::display::draw_number(190, 232, count, 0xffffff, 3);
        host::display::fill_rect(100, 300, 140, 34, 0x223328);
        host::display::draw_string(112, 310, "LEAVE CLUB", 0x88aa99, 1);
        if click == 1 {
            let px: i32 = host::display::pointer_x();
            let py: i32 = host::display::pointer_y();
            if px >= 100 && px < 240 && py >= 300 && py < 334 {
                host::agent::unsubscribe();
            }
        }
    } else {
        host::display::fill_rect(76, 130, 360, 220, 0x1a1e26);
        host::display::draw_string(100, 170, "NOT A MEMBER", 0x8899aa, 3);
        host::display::draw_string(100, 240, "MEMBERS", 0x556677, 1);
        host::display::draw_number(172, 232, count, 0xffffff, 3);
        host::display::fill_rect(100, 290, 200, 44, 0xdddddd);
        host::display::draw_string(128, 304, "JOIN CLUB", 0x000000, 2);
        if click == 1 {
            let px2: i32 = host::display::pointer_x();
            let py2: i32 = host::display::pointer_y();
            if px2 >= 100 && px2 < 300 && py2 >= 290 && py2 < 334 {
                if has == 0 {
                    host::agent::request_identity();
                } else {
                    host::agent::subscribe();
                    host::agent::notify("Welcome to the club", "Your membership is live.");
                }
            }
        }
    }
    host::display::present();
}
